INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein Router ohne Netzwerkpfadtabelle Daten weiterleiten kann?', 2, '[{"text": "Nein", "correct": true, "because": "Die Tabelle ist essenziell für Routing"}, {"text": "Ja", "correct": false, "because": "Ohne Tabelle keine Weiterleitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist zentral in einer Netzwerkpfadtabelle?', 3, '[{"text": "Zieladresse", "correct": true, "because": "Bestimmt den Datenpfad"}, {"text": "Routerfarbe", "correct": false, "because": "Irrelevant"}, {"text": "Bandbreite", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen enthält eine Netzwerkpfadtabelle?', 5, '[{"text": "Zielnetzwerk", "correct": true, "because": "Leitet Daten zum Ziel"}, {"text": "Nächster Hop", "correct": true, "because": "Gibt nächste Station an"}, {"text": "Routergewicht", "correct": false, "because": "Kein Tabellenfeld"}, {"text": "Firmwareversion", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Tabelle enthält Metriken. b) Sie speichert immer historische Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, keine Historie"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Konfiguration einer Netzwerkpfadtabelle?', 4, '[{"text": "Subnetzmaske", "correct": false, "because": "Definiert Zielnetzwerk"}, {"text": "Gateway", "correct": false, "because": "Nächster Hop essenziell"}, {"text": "Routerdesign", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Tabelle statisch oder dynamisch sein kann?', 2, '[{"text": "Ja", "correct": true, "because": "Beide Varianten existieren"}, {"text": "Nein", "correct": false, "because": "Sowohl statisch als auch dynamisch möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll aktualisiert eine dynamische Tabelle?', 4, '[{"text": "OSPF", "correct": true, "because": "Berechnet optimale Pfade"}, {"text": "DHCP", "correct": false, "because": "Für IP-Vergabe"}, {"text": "FTP", "correct": false, "because": "Für Dateitransfer"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Tabelle immer nur lokale Netzwerke enthält. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Auch externe Netze möglich"}, {"text": "Ja", "correct": false, "because": "Enthält oft entfernte Netze"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss eine Tabelle manuell gepflegt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Dynamische Updates möglich"}, {"text": "Ja", "correct": false, "because": "Nur bei statischen Tabellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Felder sind typisch für eine Netzwerkpfadtabelle?', 5, '[{"text": "Zieladresse", "correct": true, "because": "Definiert Ziel"}, {"text": "Metrik", "correct": true, "because": "Bewertet Pfad"}, {"text": "Routername", "correct": false, "because": "Nicht Teil der Tabelle"}, {"text": "Farbcodierung", "correct": false, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Pflege einer Tabelle?', 4, '[{"text": "Genaue Zielnetze", "correct": true, "because": "Sichert korrektes Routing"}, {"text": "Schnelle Konfiguration", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Visuelle Darstellung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Default-Gateway ist oft enthalten. b) Es ersetzt Firewalls.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Firewall ist separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine funktionierende Tabelle?', 3, '[{"text": "Zielnetzwerk", "correct": false, "because": "Kern der Weiterleitung"}, {"text": "Subnetzmaske", "correct": false, "because": "Definiert Netzbereich"}, {"text": "Routergewicht", "correct": true, "because": "Kein Tabellenfeld"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich eine statische Route hinzufüge?', 4, '[{"text": "Ziel und Gateway manuell setzen", "correct": true, "because": "Definiert festen Pfad"}, {"text": "Protokoll wie OSPF aktivieren", "correct": false, "because": "Dynamisch, nicht statisch"}, {"text": "Nur IP neu starten", "correct": false, "because": "Keine Route hinzugefügt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Metriken immer die Bandbreite messen. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Metriken können Hops, Kosten messen"}, {"text": "Ja", "correct": false, "because": "Nicht nur Bandbreite"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, die beste Route auszuwählen?', 4, '[{"text": "Niedrigste Metrik", "correct": true, "because": "Optimiert Pfadwahl"}, {"text": "Höchste Bandbreite", "correct": false, "because": "Nur ein Faktor"}, {"text": "Zufällige Wahl", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Enthält eine Tabelle immer alle Netzwerke?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bekannte Netze"}, {"text": "Ja", "correct": false, "because": "Begrenzte Einträge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine dynamische Tabelle?', 5, '[{"text": "Automatische Updates", "correct": true, "because": "Passt sich Änderungen an"}, {"text": "Weniger Wartung", "correct": true, "because": "Protokolle übernehmen Arbeit"}, {"text": "Kleinere Größe", "correct": false, "because": "Größe variiert"}, {"text": "Bessere Optik", "correct": false, "because": "Kein technischer Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Analyse einer Tabelle unwichtig?', 3, '[{"text": "Gateway-Adresse", "correct": false, "because": "Definiert nächsten Hop"}, {"text": "Metrik-Werte", "correct": false, "because": "Beeinflussen Pfadwahl"}, {"text": "Tabellenlayout", "correct": true, "because": "Nur visuelle Darstellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn Daten nicht ankommen?', 4, '[{"text": "Tabelle auf falsche Routen prüfen", "correct": true, "because": "Fehlerhafte Einträge finden"}, {"text": "Router ausschalten", "correct": false, "because": "Keine Lösung"}, {"text": "Farben ändern", "correct": false, "because": "Irrelevant"}]');
